"""Build the gallery from generated scenes, browser checks and visual ratings."""
import html
import json
from pathlib import Path
import statistics

ROOT = Path(__file__).resolve().parents[1] / 'experiments' / 'monuments'
summary = json.loads((ROOT / 'generation-summary.json').read_text())
checks = {row['slug']: row for row in json.loads((ROOT / 'render-results.json').read_text())}
# Recognizability, visual finish, framing, working interaction; each out of ten.
ratings = {
 '01-golden-gate': ([8,6,4,10], 'Recognizable towers, deck and paired cables. The right approach is cropped and the sky occupies too much of the frame.'),
 '02-eiffel': ([8,7,5,10], 'Strong lattice silhouette and a detailed miniature base. The spire and base are clipped; the lower structure is heavily cross-braced.'),
 '03-taj-mahal': ([8,7,5.5,10], 'Readable onion domes, four minarets and warm ivory palette. The garden and pool are cropped; the facade is simplified.'),
 '04-colosseum': ([0,0,0,0], 'Original fails to parse because of an invalid color expression. A separate one-line syntax repair reveals a detailed arena, but broad ring slabs bridge the intended broken wall.'),
 '05-liberty': ([6.5,6,8,10], 'Clear torch, crown, tablet and island. The figure is small and blocky, the torch resembles a cone, and the harbor reads as solid ground.'),
 '06-opera-house': ([3.5,4.5,7.5,10], 'Clean ivory forms and terracotta podium, but the tall upright shells miss the broad interlocking Opera House silhouette. Background blocks distract.'),
 '07-pyramids': ([8,6,4.5,10], 'Convincing pyramid shapes and warm desert palette. The nearest pyramid is cropped, the third is mostly hidden and surface banding is visible.'),
 '08-big-ben': ([8,7.5,6,10], 'Readable clock faces and effective night lighting. Simplified Gothic detail, a very tall plain spire and almost no margin above its finial.'),
 '09-christ': ([5,4.5,8,10], 'The outstretched-arm silhouette reads, but the anatomy is doll-like, the robe has spiky folds and low contrast weakens the small figure.'),
 '10-tower-bridge': ([8,7.5,8,10], 'Strong isometric composition, paired towers, blue walkways and complete river crossing. Roofs and surrounding buildings are simplified.'),
}
rows=[]
for item in summary['results']:
    row=dict(item)
    row['dimensions'], row['assessment'] = ratings[row['slug']]
    row['score'] = round(sum(a*b for a,b in zip(row['dimensions'], [.4,.3,.2,.1]))+1e-8,1)
    row['checks'] = checks[row['slug']]
    rows.append(row)
ranked=sorted(rows,key=lambda row:row['score'],reverse=True)
for rank,row in enumerate(ranked,1): row['rank']=rank
cost=sum(row['usage']['cost'] for row in rows)
stats={'total_cost_usd':cost,'generation_wall_seconds':summary['wall_seconds'],'median_generation_seconds':statistics.median(row['elapsed_seconds'] for row in rows),'original_render_successes':sum(bool(row['checks'].get('rendered')) for row in rows),'total_tokens':sum(row['usage']['total_tokens'] for row in rows),'reasoning_tokens':sum(row['usage']['completion_tokens_details']['reasoning_tokens'] for row in rows)}
(ROOT/'ratings.json').write_text(json.dumps({'method':'Subjective review of every initial 1200x800 screenshot, plus browser interaction checks. Score = 40% recognizability + 30% visual finish + 20% framing + 10% working interaction. Failed original receives 0. Different monuments and prompts are confounded.','stats':stats,'results':rows,'repair':{'slug':'04-colosseum-repaired','change':'Replace invalid color expression 0xcdb astray||0xcdb18e with 0xcdb18e. No geometry changes.','dimensions':[8,6.5,7.5,10],'score':7.7}},indent=2))
esc=html.escape
cards=[]
for row in rows:
    slug=row['slug']; failed=not row['checks'].get('rendered')
    repair='<button data-scene="04-colosseum-repaired" data-title="Colosseum — syntax repair">View repaired scene · 7.7/10</button><a href="04-colosseum-repaired.png" target="_blank">Repaired preview</a>' if failed else ''
    cards.append(f'''<article class="card" data-rank="{row['rank']}" data-order="{slug[:2]}"><div class="thumbnail"><img src="{slug}.png" alt="{esc(row['name'])} initial generated scene" loading="lazy"><span class="badge">{row['score']:.1f}<small>/10</small></span>{'<span class="failure">Original failed to render</span>' if failed else ''}</div><div class="body"><div class="eyebrow">EXPERIMENT {slug[:2]} · RANK {row['rank']}</div><h2>{esc(row['name'])}</h2><div class="approach">{esc(row['approach'])}</div><p>{esc(row['assessment'])}</p><div class="metrics"><span>{row['elapsed_seconds']:.2f}s</span><span>${row['usage']['cost']:.6f}</span><span>{row['usage']['total_tokens']:,} tokens</span></div><div class="actions"><button data-scene="{slug}" data-title="{esc(row['name'])}">{'View failed original' if failed else 'Explore in 3D'}</button>{repair}<a href="{slug}.html" target="_blank">Source scene ↗</a></div><details><summary>Prompt &amp; scoring</summary><dl><dt>Recognizability</dt><dd>{row['dimensions'][0]}/10</dd><dt>Visual finish</dt><dd>{row['dimensions'][1]}/10</dd><dt>Framing</dt><dd>{row['dimensions'][2]}/10</dd><dt>Working interaction</dt><dd>{row['dimensions'][3]}/10</dd></dl><pre>{esc(row['prompt'])}</pre><a href="{slug}.json" target="_blank">API metadata</a></details></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Monuments · Muse Ember experiments</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#10151a;color:#eef2f3}*{box-sizing:border-box}body{margin:0}main{max-width:1560px;margin:auto;padding:52px 36px}.kicker{color:#a8d5bb;font-size:12px;letter-spacing:.2em;font-weight:700}h1{font-size:clamp(34px,5vw,64px);letter-spacing:-.05em;line-height:1.05;margin:16px 0}header p{max-width:820px;color:#b3bdc6;line-height:1.7}.stats{display:flex;gap:32px;flex-wrap:wrap;margin:28px 0 36px}.stats strong{font-size:26px;display:block}.stats span{color:#9aa9b4;font-size:13px}.toolbar{display:flex;justify-content:space-between;gap:20px;align-items:center;border-top:1px solid #303b43;padding:22px 0}.toolbar p{margin:0;color:#aab7c1}select,button{font:inherit;color:#edf7f1;background:#233c32;border:1px solid #456254;border-radius:7px;padding:9px 12px;cursor:pointer}select{background:#1e272e}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{background:#1a2229;border:1px solid #303b43;border-radius:12px;overflow:hidden}.thumbnail{position:relative}.thumbnail img{width:100%;aspect-ratio:3/2;object-fit:cover;display:block}.badge{position:absolute;top:16px;right:16px;background:#10191ee8;border:1px solid #5b736b;color:#e1f6e9;padding:8px 11px;border-radius:8px;font-weight:700;font-size:23px}.badge small{font-size:12px;color:#b1c4b8}.failure{position:absolute;bottom:18px;left:20px;color:#fff0e2;background:#713e2d;padding:8px 12px;border-radius:6px}.body{padding:24px}.eyebrow{font-size:10px;letter-spacing:.14em;color:#9faeb8;font-weight:700}h2{font-size:25px;letter-spacing:-.025em;margin:8px 0}.approach{color:#aad8bb;font-size:14px}.body p{color:#b8c4cd;line-height:1.6;min-height:76px;font-size:14px}.metrics{display:flex;gap:15px;color:#9fafba;font-size:12px;border-top:1px solid #35404a;padding-top:15px}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:18px 0}a{color:#a9d6e7;font-size:13px}details{border-top:1px solid #35404a;padding-top:13px}summary{font-size:13px;color:#aebec7;cursor:pointer}pre{white-space:pre-wrap;color:#b6c3cc;line-height:1.6;font:12px ui-monospace,monospace;background:#131a20;padding:14px;border-radius:6px;max-height:380px;overflow:auto}dl{display:grid;grid-template-columns:1fr 80px;gap:6px;font-size:13px}dd{margin:0}footer{color:#95a6b2;font-size:13px;line-height:1.7;margin-top:30px}dialog{width:min(1400px,96vw);height:90vh;max-width:none;max-height:none;padding:0;border:1px solid #546a70;border-radius:12px;background:#111b22;color:white}dialog::backdrop{background:#050a10d9}dialog .bar{height:64px;display:flex;align-items:center;gap:16px;padding:12px 18px}dialog .bar strong{flex:1}dialog iframe{border:0;width:100%;height:calc(100% - 64px);background:#172129}@media(max-width:800px){main{padding:30px 16px}.grid{grid-template-columns:1fr}.toolbar{align-items:flex-start}.stats{gap:24px}.body p{min-height:0}}
</style></head><body><main><header><div class="kicker">MUSE EMBER · THREE.JS · 10 PARALLEL GENERATIONS</div><h1>Ten monuments.<br>Ten visual directions.</h1><p>Every scene came from the same model with medium reasoning and a shared rendering contract. Each monument received a different art direction. Explore the original outputs, read the exact prompts and compare the results.</p></header>'''
page+=f'''<section class="stats"><div><strong>9 / 10</strong><span>originals rendered</span></div><div><strong>{stats['generation_wall_seconds']:.1f}s</strong><span>parallel generation wall time</span></div><div><strong>${cost:.4f}</strong><span>total API-reported cost</span></div><div><strong>Tower Bridge</strong><span>highest rated · 8.1/10</span></div></section><div class="toolbar"><p>All 10 first attempts · click a scene to orbit and zoom</p><label>Order <select id="sort"><option value="order">Experiment order</option><option value="rank">Highest score</option></select></label></div><section class="grid" id="grid">{''.join(cards)}</section>'''
page+='''<footer><strong>How the scores work</strong><br>Subjective review of every initial 1200 × 800 screenshot. Recognizability 40%, visual finish 30%, framing 20%, working interaction 10%. Nine originals passed render, drag, zoom and resize checks with no captured JavaScript errors. The Colosseum original failed with a syntax error; a separately labeled copy replaces one invalid color expression and passes all four checks. Its repaired score is 7.7/10.<br><br>Each prompt was tried once on a different monument. These results compare complete outputs; they cannot isolate which prompt style is best across monuments. No reference images were supplied. Costs include reasoning tokens. <a href="ratings.json">Ratings and usage data</a> · <a href="contact-sheet.html">All previews</a></footer></main><dialog id="viewer"><div class="bar"><strong id="viewer-title"></strong><span>Drag to orbit · scroll to zoom</span><button id="close">Close ✕</button></div><iframe id="scene" title="Interactive monument" sandbox="allow-scripts allow-same-origin"></iframe></dialog><script>
const viewer=document.getElementById('viewer'), frame=document.getElementById('scene');
document.querySelectorAll('[data-scene]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('viewer-title').textContent=button.dataset.title;frame.src=button.dataset.scene+'.html';viewer.showModal()}));
function closeScene(){frame.removeAttribute('src');viewer.close()}
document.getElementById('close').addEventListener('click',closeScene);
viewer.addEventListener('cancel',event=>{event.preventDefault();closeScene()});
document.getElementById('sort').addEventListener('change',event=>{const key=event.target.value;const grid=document.getElementById('grid');Array.from(grid.children).sort((a,b)=>Number(a.dataset[key])-Number(b.dataset[key])).forEach(card=>grid.appendChild(card))});
</script></body></html>'''
(ROOT/'index.html').write_text(page)
contact='''<!doctype html><meta charset="utf-8"><title>All ten monument previews</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#10151a;color:#e7eff3;font:16px system-ui}h1{margin:0 0 8px;font-size:30px}header p{margin:0 0 24px;color:#b3c2cb}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}article{background:#1a252d;border-radius:9px;overflow:hidden}img{width:100%;aspect-ratio:3/2;object-fit:cover;display:block}section{padding:12px 16px}h2{margin:0 0 5px;font-size:18px}p{margin:0;color:#adc2cf;font-size:13px}.score{float:right;color:#b9e5c5}.failed{color:#ffbba1}footer{margin-top:20px;color:#aabdc8;font-size:13px}</style><header><h1>Muse Ember · 10 Three.js monuments</h1><p>Ten parallel first attempts · original camera views · total $'''+f'{cost:.4f}'+''' · subjective scores / 10</p></header><div class="grid">'''
for row in rows:
    failed=row['slug']=='04-colosseum'
    image_name='04-colosseum-repaired' if failed else row['slug']
    score='0.0 original · 7.7 repaired' if failed else f"{row['score']:.1f}"
    contact+=f'''<article><img src="{image_name}.png"><section><h2>{row['slug'][:2]} · {esc(row['name'])}<span class="score">{score}</span></h2><p>{esc(row['approach'])}{' · <span class="failed">Preview uses one-line syntax repair</span>' if failed else ''}</p></section></article>'''
contact+='</div><footer>Original Colosseum failed with a JavaScript syntax error. All other artwork is unedited. Different subjects and prompt styles were varied together.</footer>'
(ROOT/'contact-sheet.html').write_text(contact)
report=['# Muse Ember monument experiment','',f"Ten API requests launched in parallel. Generation wall time {stats['generation_wall_seconds']:.3f}s. Total API-reported cost ${cost:.7f}. Median request {stats['median_generation_seconds']:.3f}s. {stats['total_tokens']:,} total tokens, including {stats['reasoning_tokens']:,} reasoning tokens.",'','9/10 original scenes rendered and passed orbit, zoom and resize checks. Colosseum failed with a syntax error. The separately preserved repair substitutes `0xcdb18e` for `0xcdb astray||0xcdb18e`; it rendered and passed the same checks. No geometry was changed.','','Scores are subjective: 40% recognizability, 30% visual finish, 20% framing and 10% working interaction. All initial screenshots were inspected. Subjects and prompt styles vary together, so this is an output comparison, not a controlled prompt benchmark.','','| Rank | Monument | Prompt approach | Score | Time | Cost |','|---|---|---|---|---|---|']
for row in ranked: report.append(f"| {row['rank']} | {row['name']} | {row['approach']} | {row['score']:.1f} | {row['elapsed_seconds']:.2f}s | ${row['usage']['cost']:.7f} |")
report+=['','The repaired Colosseum scores 7.7/10, separately from its failed first attempt.','','## Visual observations','']
for row in rows: report.append(f"- **{row['name']}** — {row['assessment']}")
(ROOT/'REPORT.md').write_text('\n'.join(report)+'\n')
print(json.dumps(stats,indent=2))
print('Ranking:', [(r['name'],r['score']) for r in ranked])
